from urllib.parse import quote

import frappe
from frappe import _

from pulse.utils.access import has_pulse_access, has_pulse_write

no_cache = 1


def get_context(context):
    """Boot data for the Pulse Vue SPA (www/pulse.html is generated by the build).

    The frappe-ui build injects `window[key] = boot[key]` for each key below,
    giving the SPA its CSRF token and session context for authenticated calls.
    """
    # Not logged in -> Frappe login, then bounce back to where they were going, so an
    # emailed link to a task still opens that task after sign-in.
    if frappe.session.user == "Guest":
        request = getattr(frappe.local, "request", None)
        target = request.full_path.rstrip("?") if request else "/pulse"
        frappe.local.flags.redirect_location = "/login?redirect-to=" + quote(target, safe="")
        raise frappe.Redirect

    # Logged in but without any Pulse role -> no access to the SPA.
    if not has_pulse_access():
        frappe.throw(_("You do not have permission to use Pulse."), frappe.PermissionError)

    context.no_cache = 1
    context.boot = {
        "csrf_token": frappe.sessions.get_csrf_token(),
        "sitename": frappe.local.site,
        "user": frappe.session.user,
        "can_write": has_pulse_write(),
        # realtime: the SPA connects to socket.io on this port, in a namespace
        # named after the site (Frappe's socketio rejects any other namespace).
        "socketio_port": frappe.conf.get("socketio_port") or 9000,
    }
    frappe.db.commit()
    return context
